import{_ as a}from"./chunks/1732843327250.DvQIYtMs.js";import{_ as e,c as r,o as n,ag as l}from"./chunks/framework.CPtCmog4.js";const C=JSON.parse('{"title":"TCP","description":"","frontmatter":{},"headers":[],"relativePath":"network/TCP.md","filePath":"network/TCP.md","lastUpdated":1780143966000}'),s={name:"network/TCP.md"};function d(i,t,o,h,p,c){return n(),r("div",null,t[0]||(t[0]=[l('<h1 id="tcp" tabindex="-1">TCP <a class="header-anchor" href="#tcp" aria-label="Permalink to &quot;TCP&quot;">​</a></h1><p>TCP(传输控制协议, Transmission Control Protocol) 是一种<strong>面向连接的、可靠的、基于字节流的</strong>传输层通信协议, 广泛应用于互联网中，它旨在提供可靠的端到端通信。</p><h3 id="tcp特点" tabindex="-1">TCP特点 <a class="header-anchor" href="#tcp特点" aria-label="Permalink to &quot;TCP特点&quot;">​</a></h3><ul><li>一对一</li><li>面向字节</li><li>确认机制</li><li>超时重传</li></ul><h3 id="tcp帧结构" tabindex="-1">TCP帧结构 <a class="header-anchor" href="#tcp帧结构" aria-label="Permalink to &quot;TCP帧结构&quot;">​</a></h3><img src="'+a+`" alt="TCP帧结构" style="zoom:60%;"><h3 id="拥塞控制" tabindex="-1">拥塞控制 <a class="header-anchor" href="#拥塞控制" aria-label="Permalink to &quot;拥塞控制&quot;">​</a></h3><p>发送窗口 = min(接收窗口 rwnd, 拥塞窗口 cwnd)</p><ul><li>慢开始：连接建立后，拥塞窗口 cwnd 从1个MSS开始，每收到一个确认就翻倍，呈指数增长</li><li>拥塞避免：当cwnd达到慢开始门限(ssthresh)后，改为线性增长（每RTT加1个MSS）</li><li>快重传：收到3个重复确认后立即重传丢失的报文段，不等超时计时器到期</li><li>快恢复：执行快重传后，将ssthresh和cwnd减半，进入拥塞避免阶段（而非慢开始）</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cwnd增长示意：</span></span>
<span class="line"><span>慢开始: 1 → 2 → 4 → 8 → 16 (达到ssthresh)</span></span>
<span class="line"><span>拥塞避免: 16 → 17 → 18 → 19 → ... (线性增长)</span></span>
<span class="line"><span>超时丢包: ssthresh = cwnd/2, cwnd = 1, 重新慢开始</span></span>
<span class="line"><span>3个重复ACK: ssthresh = cwnd/2, cwnd = ssthresh, 进入快恢复</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="流量控制" tabindex="-1">流量控制 <a class="header-anchor" href="#流量控制" aria-label="Permalink to &quot;流量控制&quot;">​</a></h3><p>发送设备和接收设备处理信息的能力、网络的负载能力都会导致数据传输是否可靠。为此TCP有着一系列控制流量的办法。</p><ul><li>滑动窗口机制：接收方在确认帧中通过&quot;窗口&quot;字段告知发送方自己的接收缓冲区剩余大小(rwnd)，发送方据此调整发送速度</li><li>零窗口探测：当接收方窗口为0时，发送方定期发送零窗口探测报文，询问接收方窗口是否已恢复</li><li>糊涂窗口综合征避免：接收方不通告小窗口，发送方不发送小数据段（Nagle算法）</li></ul><h3 id="三次握手" tabindex="-1">三次握手 <a class="header-anchor" href="#三次握手" aria-label="Permalink to &quot;三次握手&quot;">​</a></h3><table tabindex="0"><thead><tr><th>序号</th><th>方向</th><th></th><th></th></tr></thead><tbody><tr><td>1</td><td>Client → Server</td><td>Client Hello</td><td>SYN=1</td></tr><tr><td>2</td><td>Server→ Client</td><td>Server Hello Server ACK</td><td>SYN=1 ACK=1</td></tr><tr><td>3</td><td>Client → Server</td><td></td><td>ACK=1</td></tr></tbody></table><h3 id="四次挥手" tabindex="-1">四次挥手 <a class="header-anchor" href="#四次挥手" aria-label="Permalink to &quot;四次挥手&quot;">​</a></h3><table tabindex="0"><thead><tr><th>序号</th><th>方向</th><th></th></tr></thead><tbody><tr><td>1</td><td>Client → Server</td><td>FIN=1</td></tr><tr><td>2</td><td>Server→ Client</td><td>ACK=1</td></tr><tr><td>3</td><td>Server→ Client</td><td>FIN=1，ACK=1</td></tr><tr><td>4</td><td>Client → Server</td><td>ACK=1</td></tr></tbody></table><h3 id="保活机制" tabindex="-1">保活机制 <a class="header-anchor" href="#保活机制" aria-label="Permalink to &quot;保活机制&quot;">​</a></h3><p>建立TCP连接的双方长时间无数据交互时，触发保活机制。TCP发送探测报文，若有响应则刷新保活时间，若无响应则断开连接。</p><ul><li>默认保活时间：2小时（7200秒）</li><li>探测间隔：75秒</li><li>探测次数：9次失败后断开</li></ul><p>注意：保活机制可能被中间设备（NAT、防火墙）干扰，应用层通常自行实现心跳机制更为可靠。</p>`,21)]))}const m=e(s,[["render",d]]);export{C as __pageData,m as default};
